  "codebook": {
    "definition": "Credit-claiming refers to statements in which a legislator attempts to generate the belief that they are personally responsible for a desirable government action. This includes securing federal funding, passing legislation, adopting amendments, or successfully influencing a federal agency's decision to bring tangible benefits to their state or constituency.",
    "clarification": "Include texts where the senator announces the receipt of a federal grant or funding for their state/district, as this is a traditional method of claiming credit by associating themselves with the benefit. Also include statements emphasizing their role in authoring an amendment that was adopted, successfully passing a bill through the chamber, or intervening with a federal agency to secure a specific benefit or policy change.",
    "positive_examples": [
      {
        "text": "Senator Smith announced today that the local Fire Department will receive a $100,000 grant, funding he fought to secure during the appropriations process.",
        "explanation": "This text counts as credit-claiming because the senator is announcing a localized federal benefit and explicitly claiming a role in securing the funds."
      },
      {
        "text": "The Senate passed the defense bill today, which included Senator Doe's amendment to provide housing benefits for veterans.",
        "explanation": "This counts as credit-claiming because the senator points to a successful legislative action (the passage of a bill/amendment) for which they are responsible."
      },
      {
        "text": "After Senator Jones intervened and wrote a letter to the DOT, the agency has agreed to approve the new highway bypass for our county.",
        "explanation": "This is credit-claiming because the senator asserts that their specific intervention caused the federal agency to deliver a desirable outcome."
      }
    ],
    "negative_clarification": "Exclude texts where a senator merely introduces legislation that has not yet passed, takes a position on a national issue, criticizes a policy, or expresses support for an action without claiming a role in bringing it about. General oversight actions, requests to agencies that have not yet yielded results, and announcements of town halls are also excluded.",
    "negative_examples": [
      {
        "text": "Senator Roe today introduced legislation to reform the tax code and lower rates for working families.",
        "explanation": "This is not credit-claiming; it is position-taking. Merely introducing a bill does not constitute a finalized legislative success or a tangible benefit."
      },
      {
        "text": "I strongly urge the administration to reverse its disastrous policy on trade and protect American workers.",
        "explanation": "This is position-taking and criticism. The senator is demanding action, not claiming credit for a successful outcome."
      },
      {
        "text": "Senator Lee expressed deep disappointment today that the Senate rejected his amendment to increase education funding.",
        "explanation": "Although the senator authored an amendment, its failure means there is no benefit or success for which to claim credit."
      }
    ]
  }
}
